public class Search {
    static long probes;

    // Index of key in the sorted array a, or -1. One probe = one comparison of key with an element.
    static int find(int[] a, int key) {
        int left = 0;
        int right = a.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            probes++;
            if (a[mid] == key) {
                return mid;
            }
            if (key > a[mid]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
}

